// Command notes runs the notes HTTP service: notes <port>.
// The SQLite database path is read from the NOTES_DB environment variable.
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/api"
	"notes/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log, os.Args[1:]); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger, args []string) error {
	if len(args) != 1 {
		return errors.New("usage: notes <port>")
	}
	port, err := strconv.ParseUint(args[0], 10, 16)
	if err != nil {
		return fmt.Errorf("invalid port %q", args[0])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	st, err := store.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer st.Close()

	addr := net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           api.New(st, log).Handler(),
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       2 * time.Minute,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", addr, "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}

package api

import "net/http"

// Owned by the crud branch.

// handleUpdateNote serves PUT /notes/{id}. The request replaces the whole
// note: an omitted body or tags becomes "" or [].
func (s *Server) handleUpdateNote(w http.ResponseWriter, r *http.Request) {
	id, ok := s.noteID(w, r)
	if !ok {
		return
	}
	in, err := decodeNoteInput(w, r)
	if err != nil {
		s.writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	n, err := s.store.Update(r.Context(), id, in)
	if err != nil {
		s.writeStoreError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, n)
}

// handleDeleteNote serves DELETE /notes/{id}.
func (s *Server) handleDeleteNote(w http.ResponseWriter, r *http.Request) {
	id, ok := s.noteID(w, r)
	if !ok {
		return
	}
	if err := s.store.Delete(r.Context(), id); err != nil {
		s.writeStoreError(w, r, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

package api

import (
	"context"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"notes/internal/store"
)

func newTestServer(t *testing.T) http.Handler {
	t.Helper()
	st, err := store.Open(context.Background(), filepath.Join(t.TempDir(), "notes.db"))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { st.Close() })
	return New(st, slog.New(slog.DiscardHandler)).Handler()
}

func do(t *testing.T, h http.Handler, method, path, body string) (int, string) {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(method, path, strings.NewReader(body)))
	b, _ := io.ReadAll(rec.Body)
	return rec.Code, string(b)
}

func TestUpdateDeleteHandlers(t *testing.T) {
	h := newTestServer(t)
	if code, _ := do(t, h, "POST", "/notes", `{"title":"a","tags":["x"]}`); code != http.StatusCreated {
		t.Fatalf("create: %d", code)
	}

	for _, tc := range []struct {
		method, path, body string
		want               int
	}{
		{"PUT", "/notes/1", `{"title":" new ","tags":["b","a","b"]}`, http.StatusOK},
		{"PUT", "/notes/1", `{"title":""}`, http.StatusBadRequest},
		{"PUT", "/notes/1", `not json`, http.StatusBadRequest},
		{"PUT", "/notes/9", `{"title":"x"}`, http.StatusNotFound},
		{"PUT", "/notes/0", `{"title":"x"}`, http.StatusNotFound},
		{"PUT", "/notes/abc", `{"title":"x"}`, http.StatusNotFound},
		{"DELETE", "/notes/abc", ``, http.StatusNotFound},
		{"DELETE", "/notes/-1", ``, http.StatusNotFound},
		{"DELETE", "/notes/9", ``, http.StatusNotFound},
		{"DELETE", "/notes", ``, http.StatusMethodNotAllowed},
		{"PATCH", "/notes/1", `{}`, http.StatusMethodNotAllowed},
	} {
		if code, body := do(t, h, tc.method, tc.path, tc.body); code != tc.want {
			t.Errorf("%s %s %s: status %d (%s), want %d", tc.method, tc.path, tc.body, code, body, tc.want)
		}
	}

	if _, body := do(t, h, "GET", "/notes/1", ""); strings.TrimSpace(body) != `{"id":1,"title":"new","body":"","tags":["a","b"]}` {
		t.Errorf("after update: %s", body)
	}

	code, body := do(t, h, "DELETE", "/notes/1", "")
	if code != http.StatusNoContent || body != "" {
		t.Errorf("delete: %d %q", code, body)
	}
	if code, _ := do(t, h, "GET", "/notes/1", ""); code != http.StatusNotFound {
		t.Errorf("get after delete: %d", code)
	}
	if code, _ := do(t, h, "PUT", "/notes/1", `{"title":"x"}`); code != http.StatusNotFound {
		t.Errorf("put after delete: %d", code)
	}
}

package api

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"slices"
	"strconv"
	"strings"
	"unicode/utf8"

	"notes/internal/store"
)

const (
	maxBodyBytes   = 1 << 20
	maxTitleLength = 200
	maxTagLength   = 32
)

// errBadRequest marks validation errors; its message is shown to the client.
type errBadRequest struct{ msg string }

func (e errBadRequest) Error() string { return e.msg }

func badRequest(format string, args ...any) error {
	return errBadRequest{msg: fmt.Sprintf(format, args...)}
}

// decodeNoteInput reads and validates a {title, body?, tags?} request body,
// as used by POST /notes and PUT /notes/{id}. Omitted body and tags become ""
// and []. A returned errBadRequest should be reported as 400.
func decodeNoteInput(w http.ResponseWriter, r *http.Request) (store.NoteInput, error) {
	data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		if _, ok := errors.AsType[*http.MaxBytesError](err); ok {
			return store.NoteInput{}, badRequest("request body too large")
		}
		return store.NoteInput{}, badRequest("cannot read request body")
	}
	return parseNoteInput(data)
}

// parseNoteInput validates and normalizes a JSON note object.
func parseNoteInput(data []byte) (store.NoteInput, error) {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(data, &fields); err != nil || fields == nil {
		return store.NoteInput{}, badRequest("request body must be a JSON object")
	}

	var in store.NoteInput

	raw, ok := fields["title"]
	if !ok {
		return in, badRequest("title is required")
	}
	if err := unmarshalString(raw, &in.Title); err != nil {
		return in, badRequest("title must be a string")
	}
	in.Title = strings.TrimSpace(in.Title)
	if n := utf8.RuneCountInString(in.Title); n < 1 || n > maxTitleLength {
		return in, badRequest("title must be 1-%d characters", maxTitleLength)
	}

	if raw, ok := fields["body"]; ok {
		if err := unmarshalString(raw, &in.Body); err != nil {
			return in, badRequest("body must be a string")
		}
	}

	in.Tags = []string{}
	if raw, ok := fields["tags"]; ok {
		tags, err := parseTags(raw)
		if err != nil {
			return in, err
		}
		in.Tags = tags
	}
	return in, nil
}

// unmarshalString decodes raw into s, rejecting anything but a JSON string
// (including null, which json.Unmarshal would otherwise accept).
func unmarshalString(raw json.RawMessage, s *string) error {
	if len(raw) == 0 || raw[0] != '"' {
		return errors.New("not a string")
	}
	return json.Unmarshal(raw, s)
}

// parseTags decodes, validates, deduplicates and sorts a JSON array of tags.
func parseTags(raw json.RawMessage) ([]string, error) {
	var items []json.RawMessage
	if len(raw) == 0 || raw[0] != '[' || json.Unmarshal(raw, &items) != nil {
		return nil, badRequest("tags must be an array of strings")
	}
	tags := make([]string, 0, len(items))
	for _, item := range items {
		var tag string
		if err := unmarshalString(item, &tag); err != nil {
			return nil, badRequest("tags must be an array of strings")
		}
		if !ValidTag(tag) {
			return nil, badRequest("invalid tag %q: must be 1-%d characters from a-z, 0-9 and -", tag, maxTagLength)
		}
		tags = append(tags, tag)
	}
	slices.Sort(tags)
	return slices.Compact(tags), nil
}

// ValidTag reports whether tag is 1-32 characters from a-z, 0-9 and '-'.
func ValidTag(tag string) bool {
	if len(tag) < 1 || len(tag) > maxTagLength {
		return false
	}
	for i := 0; i < len(tag); i++ {
		c := tag[i]
		if !('a' <= c && c <= 'z' || '0' <= c && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// parseNoteID parses a note id path segment. ok is false unless s is a
// positive decimal integer.
func parseNoteID(s string) (id int64, ok bool) {
	if s == "" || strings.TrimLeft(s, "0123456789") != "" {
		return 0, false
	}
	id, err := strconv.ParseInt(s, 10, 64)
	if err != nil || id < 1 {
		return 0, false
	}
	return id, true
}

package api

import (
	"errors"
	"slices"
	"strings"
	"testing"
)

func TestParseNoteInput(t *testing.T) {
	in, err := parseNoteInput([]byte(`{"title":"  hi  ","body":"b","tags":["z","a-1","z"],"extra":1}`))
	if err != nil {
		t.Fatal(err)
	}
	if in.Title != "hi" || in.Body != "b" || !slices.Equal(in.Tags, []string{"a-1", "z"}) {
		t.Fatalf("got %+v", in)
	}

	in, err = parseNoteInput([]byte(`{"title":"x"}`))
	if err != nil {
		t.Fatal(err)
	}
	if in.Body != "" || in.Tags == nil || len(in.Tags) != 0 {
		t.Fatalf("defaults: got %+v", in)
	}
}

func TestParseNoteInputErrors(t *testing.T) {
	for _, body := range []string{
		``, `{"title": `, `[]`, `null`, `"x"`, `{}`, `{"title":"x"} {}`,
		`{"title":null}`, `{"title":3}`, `{"title":"   "}`, `{"title":"` + strings.Repeat("é", 201) + `"}`,
		`{"title":"x","body":3}`, `{"title":"x","body":null}`,
		`{"title":"x","tags":"a"}`, `{"title":"x","tags":null}`, `{"title":"x","tags":[1]}`,
		`{"title":"x","tags":["Bad"]}`, `{"title":"x","tags":[""]}`,
		`{"title":"x","tags":["` + strings.Repeat("a", 33) + `"]}`,
	} {
		_, err := parseNoteInput([]byte(body))
		if _, ok := errors.AsType[errBadRequest](err); !ok {
			t.Errorf("%s: got err %v, want errBadRequest", body, err)
		}
	}
	if _, err := parseNoteInput([]byte(`{"title":"` + strings.Repeat("é", 200) + `"}`)); err != nil {
		t.Errorf("200-character title rejected: %v", err)
	}
}

func TestParseNoteID(t *testing.T) {
	for s, want := range map[string]bool{
		"1": true, "42": true, "007": true,
		"": false, "0": false, "-1": false, "+1": false, "abc": false, "1.5": false,
		"99999999999999999999": false,
	} {
		if _, ok := parseNoteID(s); ok != want {
			t.Errorf("parseNoteID(%q) ok = %v, want %v", s, ok, want)
		}
	}
}

package api

import (
	"net/http"
	"net/url"
	"strconv"

	"notes/internal/store"
)

// Owned by the list branch.

const (
	defaultListLimit = 100
	maxListLimit     = 100
)

type listResponse struct {
	Notes []store.Note `json:"notes"`
}

// handleListNotes serves GET /notes?tag=&q=&after=&limit=.
func (s *Server) handleListNotes(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	f, err := parseListFilter(query)
	if err != nil {
		s.writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	notes := []store.Note{}
	// No stored note can have an invalid tag (including ""), so such a
	// filter matches nothing.
	if !query.Has("tag") || ValidTag(f.Tag) {
		notes, err = s.store.List(r.Context(), f)
		if err != nil {
			s.writeInternalError(w, r, err)
			return
		}
	}
	s.writeJSON(w, http.StatusOK, listResponse{Notes: notes})
}

// parseListFilter reads the GET /notes query parameters. Only limit and
// after can be invalid; a returned error is an errBadRequest.
func parseListFilter(q url.Values) (store.ListFilter, error) {
	f := store.ListFilter{
		Tag:   q.Get("tag"),
		Query: q.Get("q"),
		Limit: defaultListLimit,
	}
	if q.Has("after") {
		after, err := strconv.ParseInt(q.Get("after"), 10, 64)
		if err != nil {
			return f, badRequest("after must be an integer")
		}
		f.After = after
	}
	if q.Has("limit") {
		limit, err := strconv.Atoi(q.Get("limit"))
		if err != nil || limit < 1 || limit > maxListLimit {
			return f, badRequest("limit must be an integer from 1 to %d", maxListLimit)
		}
		f.Limit = limit
	}
	return f, nil
}

package api

import (
	"net/url"
	"testing"

	"notes/internal/store"
)

func TestParseListFilter(t *testing.T) {
	tests := []struct {
		query string
		want  store.ListFilter
	}{
		{"", store.ListFilter{Limit: 100}},
		{"tag=a-1&q=Hi%20there&after=7&limit=5", store.ListFilter{Tag: "a-1", Query: "Hi there", After: 7, Limit: 5}},
		{"after=-3&limit=100", store.ListFilter{After: -3, Limit: 100}},
		{"limit=1", store.ListFilter{Limit: 1}},
	}
	for _, tt := range tests {
		q, err := url.ParseQuery(tt.query)
		if err != nil {
			t.Fatal(err)
		}
		got, err := parseListFilter(q)
		if err != nil {
			t.Errorf("%q: %v", tt.query, err)
			continue
		}
		if got != tt.want {
			t.Errorf("%q: got %+v, want %+v", tt.query, got, tt.want)
		}
	}
}

func TestParseListFilterErrors(t *testing.T) {
	for _, query := range []string{
		"limit=0", "limit=101", "limit=-1", "limit=", "limit=abc", "limit=1.5", "limit=99999999999999999999",
		"after=", "after=x", "after=1.5", "after=99999999999999999999",
	} {
		q, err := url.ParseQuery(query)
		if err != nil {
			t.Fatal(err)
		}
		if _, err := parseListFilter(q); err == nil {
			t.Errorf("%q: no error", query)
		} else if _, ok := err.(errBadRequest); !ok {
			t.Errorf("%q: error %T is not errBadRequest", query, err)
		}
	}
}

package api

import (
	"errors"
	"net/http"

	"notes/internal/store"
)

// handleCreateNote serves POST /notes.
func (s *Server) handleCreateNote(w http.ResponseWriter, r *http.Request) {
	in, err := decodeNoteInput(w, r)
	if err != nil {
		s.writeError(w, http.StatusBadRequest, err.Error())
		return
	}
	n, err := s.store.Create(r.Context(), in)
	if err != nil {
		s.writeInternalError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusCreated, n)
}

// handleGetNote serves GET /notes/{id}.
func (s *Server) handleGetNote(w http.ResponseWriter, r *http.Request) {
	id, ok := s.noteID(w, r)
	if !ok {
		return
	}
	n, err := s.store.Get(r.Context(), id)
	if err != nil {
		s.writeStoreError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, n)
}

// noteID extracts the {id} path value. If it is not a positive integer it
// responds with 404 and returns ok == false.
func (s *Server) noteID(w http.ResponseWriter, r *http.Request) (id int64, ok bool) {
	id, ok = parseNoteID(r.PathValue("id"))
	if !ok {
		s.writeError(w, http.StatusNotFound, "note not found")
	}
	return id, ok
}

// writeStoreError maps store errors to responses: ErrNotFound becomes 404,
// anything else 500.
func (s *Server) writeStoreError(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, store.ErrNotFound) {
		s.writeError(w, http.StatusNotFound, "note not found")
		return
	}
	s.writeInternalError(w, r, err)
}

package api

import (
	"encoding/json"
	"net/http"
)

// writeJSON writes v as a JSON response with the given status.
func (s *Server) writeJSON(w http.ResponseWriter, status int, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		s.log.Error("encode response", "err", err)
		http.Error(w, `{"error":"internal error"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(append(data, '\n'))
}

type errorBody struct {
	Error string `json:"error"`
}

// writeError writes a JSON error response {"error": msg}.
func (s *Server) writeError(w http.ResponseWriter, status int, msg string) {
	s.writeJSON(w, status, errorBody{Error: msg})
}

// writeInternalError logs err and responds with 500.
func (s *Server) writeInternalError(w http.ResponseWriter, r *http.Request, err error) {
	s.log.Error("request failed", "method", r.Method, "path", r.URL.Path, "err", err)
	s.writeError(w, http.StatusInternalServerError, "internal error")
}

// Package api implements the HTTP interface of the notes service.
package api

import (
	"encoding/json"
	"log/slog"
	"net/http"
	"strconv"
	"strings"

	"notes/internal/store"
)

// Server serves the notes HTTP API.
type Server struct {
	store *store.Store
	log   *slog.Logger
}

// New returns a Server backed by st.
func New(st *store.Store, log *slog.Logger) *Server {
	return &Server{store: st, log: log}
}

// Handler returns the HTTP handler with all routes registered. Unknown paths
// get 404 and known paths with an unsupported method get 405; both are
// decided by http.ServeMux and answered with a JSON error body.
func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /health", s.handleHealth)

	// notes.go
	mux.HandleFunc("POST /notes", s.handleCreateNote)
	mux.HandleFunc("GET /notes/{id}", s.handleGetNote)

	// crud.go
	mux.HandleFunc("PUT /notes/{id}", s.handleUpdateNote)
	mux.HandleFunc("DELETE /notes/{id}", s.handleDeleteNote)

	// list.go
	mux.HandleFunc("GET /notes", s.handleListNotes)

	// stats.go
	mux.HandleFunc("GET /stats", s.handleStats)
	mux.HandleFunc("GET /tags", s.handleTags)

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if h, pattern := mux.Handler(r); pattern == "" {
			// No route matched: the mux answers with a plain-text 404 or
			// 405 (or a path-cleaning redirect).
			h.ServeHTTP(&jsonErrorWriter{ResponseWriter: w}, r)
			return
		}
		mux.ServeHTTP(w, r)
	})
}

// jsonErrorWriter replaces the plain-text body of an error response written
// by http.Error with {"error": "<status text>"}, keeping the status code and
// headers such as Allow.
type jsonErrorWriter struct {
	http.ResponseWriter
	replaced bool
}

func (w *jsonErrorWriter) WriteHeader(code int) {
	if code < http.StatusBadRequest {
		w.ResponseWriter.WriteHeader(code)
		return
	}
	w.replaced = true
	body, _ := json.Marshal(errorBody{Error: strings.ToLower(http.StatusText(code))})
	h := w.Header()
	h.Del("X-Content-Type-Options")
	h.Set("Content-Type", "application/json")
	h.Set("Content-Length", strconv.Itoa(len(body)+1))
	w.ResponseWriter.WriteHeader(code)
	w.ResponseWriter.Write(append(body, '\n'))
}

func (w *jsonErrorWriter) Write(b []byte) (int, error) {
	if w.replaced {
		return len(b), nil // drop the original plain-text body
	}
	return w.ResponseWriter.Write(b)
}

func (s *Server) handleHealth(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Write([]byte("ok"))
}

package api

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

func TestUnmatchedRoutesAnswerJSON(t *testing.T) {
	h := newTestServer(t)
	for _, tc := range []struct {
		method, path string
		want         int
		allow        string
	}{
		{"GET", "/nope", http.StatusNotFound, ""},
		{"GET", "/notes/", http.StatusNotFound, ""},
		{"GET", "/notes/1/x", http.StatusNotFound, ""},
		{"DELETE", "/notes", http.StatusMethodNotAllowed, "GET, HEAD, POST"},
		{"POST", "/stats", http.StatusMethodNotAllowed, "GET, HEAD"},
	} {
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, httptest.NewRequest(tc.method, tc.path, nil))
		if rec.Code != tc.want {
			t.Errorf("%s %s: status %d, want %d", tc.method, tc.path, rec.Code, tc.want)
		}
		if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
			t.Errorf("%s %s: Content-Type %q", tc.method, tc.path, ct)
		}
		if body := rec.Body.String(); !strings.HasPrefix(body, `{"error":`) {
			t.Errorf("%s %s: body %q", tc.method, tc.path, body)
		}
		if got := rec.Header().Get("Allow"); got != tc.allow {
			t.Errorf("%s %s: Allow %q, want %q", tc.method, tc.path, got, tc.allow)
		}
	}
}

package api

import (
	"net/http"

	"notes/internal/store"
)

// Owned by the stats branch.

type statsResponse struct {
	Notes int64            `json:"notes"`
	Tags  map[string]int64 `json:"tags"`
}

type tagsResponse struct {
	Tags []store.TagCount `json:"tags"`
}

// handleStats serves GET /stats.
func (s *Server) handleStats(w http.ResponseWriter, r *http.Request) {
	st, err := s.store.Stats(r.Context())
	if err != nil {
		s.writeInternalError(w, r, err)
		return
	}
	resp := statsResponse{Notes: st.Notes, Tags: make(map[string]int64, len(st.Tags))}
	for _, tc := range st.Tags {
		resp.Tags[tc.Tag] = tc.Count
	}
	s.writeJSON(w, http.StatusOK, resp)
}

// handleTags serves GET /tags.
func (s *Server) handleTags(w http.ResponseWriter, r *http.Request) {
	st, err := s.store.Stats(r.Context())
	if err != nil {
		s.writeInternalError(w, r, err)
		return
	}
	s.writeJSON(w, http.StatusOK, tagsResponse{Tags: st.Tags})
}

